import * as THREE from 'three';

// A "perfect maze" (spanning tree, guaranteed fully connected) generated by
// randomized recursive backtracker, with a handful of extra walls knocked
// out afterward so it isn't a pure dead-end labyrinth — real loops for two
// players to route around each other. Grid uses odd dimensions: even
// rows/cols are always wall, odd rows/cols are room centers.
export function generateMaze(roomsX, roomsY, extraConnectionChance = 0.12) {
  const cols = roomsX * 2 + 1;
  const rows = roomsY * 2 + 1;
  const grid = Array.from({ length: rows }, () => Array(cols).fill(1));
  const visited = Array.from({ length: roomsY }, () => Array(roomsX).fill(false));

  function carve(cx, cy) {
    visited[cy][cx] = true;
    grid[cy * 2 + 1][cx * 2 + 1] = 0;
    const dirs = [[0, -1], [0, 1], [-1, 0], [1, 0]];
    for (let i = dirs.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [dirs[i], dirs[j]] = [dirs[j], dirs[i]];
    }
    for (const [dx, dy] of dirs) {
      const nx = cx + dx, ny = cy + dy;
      if (nx >= 0 && nx < roomsX && ny >= 0 && ny < roomsY && !visited[ny][nx]) {
        grid[cy * 2 + 1 + dy][cx * 2 + 1 + dx] = 0;
        carve(nx, ny);
      }
    }
  }
  carve(0, 0);

  // Knock out a few more inner walls between adjacent rooms to add loops —
  // this only ever removes walls from an already-fully-connected graph, so
  // connectivity is never at risk.
  for (let ry = 0; ry < roomsY; ry++) {
    for (let rx = 0; rx < roomsX; rx++) {
      if (rx < roomsX - 1 && Math.random() < extraConnectionChance) {
        grid[ry * 2 + 1][rx * 2 + 2] = 0;
      }
      if (ry < roomsY - 1 && Math.random() < extraConnectionChance) {
        grid[ry * 2 + 2][rx * 2 + 1] = 0;
      }
    }
  }

  return { grid, cols, rows };
}

export function isWalkable(maze, col, row) {
  if (row < 0 || row >= maze.rows || col < 0 || col >= maze.cols) return false;
  return maze.grid[row][col] === 0;
}

export function cellToWorld(col, row, maze, cellSize) {
  return {
    x: (col - (maze.cols - 1) / 2) * cellSize,
    z: (row - (maze.rows - 1) / 2) * cellSize,
  };
}

export function worldToCell(x, z, maze, cellSize) {
  return {
    col: Math.round(x / cellSize + (maze.cols - 1) / 2),
    row: Math.round(z / cellSize + (maze.rows - 1) / 2),
  };
}

export function floorCells(maze) {
  const cells = [];
  for (let row = 0; row < maze.rows; row++) {
    for (let col = 0; col < maze.cols; col++) {
      if (maze.grid[row][col] === 0) cells.push({ col, row });
    }
  }
  return cells;
}

const wallGeo = new THREE.BoxGeometry(1, 1, 1);
const wallMat = new THREE.MeshStandardMaterial({ color: 0x4a2f7a, roughness: 0.55, metalness: 0.15 });

export function buildMazeMesh(maze, cellSize) {
  const group = new THREE.Group();

  const floorW = maze.cols * cellSize;
  const floorD = maze.rows * cellSize;
  const floor = new THREE.Mesh(
    new THREE.BoxGeometry(floorW, 0.3, floorD),
    new THREE.MeshStandardMaterial({ color: 0x1c1032, roughness: 0.85 })
  );
  floor.position.y = -0.4;
  floor.receiveShadow = true;
  group.add(floor);

  const wallHeight = 1.1;
  for (let row = 0; row < maze.rows; row++) {
    for (let col = 0; col < maze.cols; col++) {
      if (maze.grid[row][col] !== 1) continue;
      const { x, z } = cellToWorld(col, row, maze, cellSize);
      const wall = new THREE.Mesh(wallGeo, wallMat);
      wall.position.set(x, wallHeight / 2 - 0.25, z);
      wall.scale.set(cellSize * 0.96, wallHeight, cellSize * 0.96);
      wall.castShadow = true;
      wall.receiveShadow = true;
      group.add(wall);
    }
  }

  return group;
}
